package com.ftk.tpip.release.domain.model;
import java.time.Instant;import java.util.Objects;
public record WorkspaceApproval(Long id,long workspaceId,String approvalStage,String approverCode,ApprovalDecision decision,String decisionComment,String evidenceSnapshot,Instant decidedAt){public WorkspaceApproval{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(workspaceId<=0)throw new IllegalArgumentException("workspaceId must be positive");approvalStage=required(approvalStage,"approvalStage",64);approverCode=required(approverCode,"approverCode",100);Objects.requireNonNull(decision);if(decisionComment!=null&&decisionComment.length()>2000)throw new IllegalArgumentException("decisionComment is too long");evidenceSnapshot=evidenceSnapshot==null?"{}":evidenceSnapshot;}private static String required(String v,String f,int max){String x=Objects.requireNonNull(v).trim();if(x.isEmpty()||x.length()>max)throw new IllegalArgumentException(f+" is blank or too long");return x;}}
